mod solution;

fn main() {
    let cases = [
    (r#"[0.42,0.32,0.23,0.52,0.25]"#, r#"0.23,0.25,0.32,0.42,0.52"#),
    (r#"[0.9,0.1]"#, r#"0.1,0.9"#),
    (r#"
[0.9,0.1]
"#, r#"0.1,0.9"#),
    (r#"  
[0.42,0.32,0.23,0.52,0.25]
  "#, r#"0.23,0.25,0.32,0.42,0.52"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS bucket-sort");
}
